import numpy as np

def generate(params, n, chip):
    branch_width = max(2, min(int(round(params['branch_width'])), n // 2))
    seg_len = max(1, int(round(params['segment_length'])))
    generations = max(1, int(round(params['generations'])))

    grid = np.zeros((n, n), dtype=bool)
    ci0, ci1, cj0, cj1 = chip
    grid[ci0:ci1+1, cj0:cj1+1] = True

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    queue = []
    for dx, dy in directions:
        ni, nj = ci0 + dx, cj0 + dy
        if 0 <= ni < n and 0 <= nj < n:
            queue.append(((ni, nj), (dx, dy), 0))

    used = set()
    for i in range(ci0, ci1+1):
        for j in range(cj0, cj1+1):
            used.add((i, j))

    while queue and len(used) < 1440:
        (i, j), (dx, dy), gen = queue.pop(0)
        if gen >= generations:
            continue

        diag_dxs = [dy, -dy]
        for sdx in diag_dxs:
            sdy = -dx
            width = branch_width
            half = width // 2

            for k in range(seg_len):
                ni = i + (dx + sdx) * k
                nj = j + (dy + sdy) * k
                if not (0 <= ni < n and 0 <= nj < n):
                    break
                for wk in range(width):
                    for wl in range(width):
                        wi = ni - half + wk
                        wj = nj - half + wl
                        if 0 <= wi < n and 0 <= wj < n:
                            if (wi, wj) not in used:
                                used.add((wi, wj))
                                grid[wi, wj] = True
            if len(used) >= 1440:
                break
            ni_end = i + (dx + sdx) * seg_len
            nj_end = j + (dy + sdy) * seg_len
            if 0 <= ni_end < n and 0 <= nj_end < n:
                queue.append(((ni_end, nj_end), (sdx, sdy), gen + 1))

    return grid
